diff --git a/src/catalog/__tests__/register.test.ts b/src/catalog/__tests__/register.test.ts
new file mode 100644
--- /dev/null
+++ b/src/catalog/__tests__/register.test.ts
@@ -0,0 +1,21 @@
+import { registerEntry } from "../register";
+
+let callCount = 0;
+jest.mock("../registryClient", () => ({
+  put: jest.fn(() => {
+    callCount += 1;
+    return Promise.resolve({ ref: `id-${callCount}` });
+  }),
+}));
+
+describe("registerEntry", () => {
+  it("registers a first entry", async () => {
+    const result = await registerEntry({ name: "A" });
+    expect(result.ref).toBe("id-1");
+  });
+
+  it("registers a second entry", async () => {
+    const result = await registerEntry({ name: "B" });
+    expect(result.ref).toBe("id-2");
+  });
+});

